const FIT_UINT16 Profile::GetFieldIndex(const FIT_UINT16 mesgNum, const FIT_UINT8 fieldNum)
{
    // Cache last message pointer to avoid repeated GetMesg linear search.
    static FIT_UINT32 lastMesgKey = 0; // mesgNum + 1, 0 = empty
    static const MESG *lastMesg = NULL;

    const MESG *mesg;
    FIT_UINT32 mkey = (FIT_UINT32)mesgNum + 1;
    if (lastMesgKey == mkey)
    {
        mesg = lastMesg;
    }
    else
    {
        mesg = GetMesg(mesgNum);
        lastMesgKey = mkey;
        lastMesg = mesg;
    }

    if (mesg == NULL)
        return FIT_UINT16_INVALID;

    // Field index cache
    static FIT_UINT32 fieldKeys[512] = {0};
    static FIT_UINT16 fieldVals[512];
    FIT_UINT32 key = ((FIT_UINT32)mesgNum << 8) | fieldNum;
    FIT_UINT32 idx = (key ^ (key >> 16)) & 511;
    FIT_UINT32 kp1 = key + 1;
    if (fieldKeys[idx] == kp1)
        return fieldVals[idx];

    FIT_UINT16 result = FIT_UINT16_INVALID;
    for (FIT_UINT16 i = 0; i < mesg->numFields; i++)
    {
        if (mesg->fields[i].num == fieldNum)
        {
            result = i;
            break;
        }
    }
    fieldKeys[idx] = kp1;
    fieldVals[idx] = result;
    return result;
}

